var o=162;var s=`162-white-and-brown-stock-preparation`;var i=`161`;var r={en:`White and Brown Stock Preparation`,ua:`Приготування світлих і темних бульйонів`};var n={short:`White and brown stocks differ mainly in whether their bones and aromatic vegetables are browned before simmering. This changes color and roasted flavor, while careful extraction and cooling remain essential to both.`,sections:[{title:`Core idea`,text:`A white stock is made without intentionally browning the main bones and vegetables. Brown stock begins by roasting them to produce deeper color and roasted aromas, then using water to extract flavors.`},{title:`Science`,text:`Browning creates additional Maillard flavors; deglazing the roasting pan dissolves browned deposits that belong in the stock. Gentle simmering limits suspended particles; gelatin develops from appropriate connective tissues during prolonged moist heat.`},{title:`How to apply`,text:`For white stock, combine prepared bones with water, gently heat, skim, then add mirepoix and herbs. For brown stock, roast bones and selected vegetables without burning, deglaze the roasting tray and simmer. Strain and promptly cool both.`},{title:`Practical experiment`,text:`Use equal masses of poultry bones for two batches; roast the bones for only the brown version. Compare aroma, hue, mouthfeel and suitability for a light chicken soup versus a dark reduction.`},{title:`Common mistakes`,text:`Dark color from burnt bones creates bitterness, not complexity. Excessive boiling clouds both versions; adding too much salt early restricts later reduction. Do not assume a brown stock contains more gelatin simply because it is darker.`},{title:`Related theories`,text:`161, 164, 165, 172.`}]};var a={short:`Світлі й темні бульйонні основи відрізняються передусім обсмажуванням кісток та ароматичних овочів перед варінням. Це змінює колір і смажені нотки, однак обом способам потрібні контроль екстракції та безпечне охолодження.`,sections:[{title:`Суть`,text:`Світлу основу готують без навмисного підрум’янення кісток та овочів. Для темної спочатку запікають ці компоненти, утворюючи насиченіший колір і смажений аромат, а потім екстрагують смак у воді.`},{title:`Наука`,text:`Реакція Майяра під час запікання створює додаткові ароматичні сполуки. Деглазування дека переносить підсмажені залишки в каструлю. Делікатне томління зменшує кількість завислих частинок, а желатин утворюється зі сполучної тканини незалежно від кольору.`},{title:`Як застосувати`,text:`Для світлої основи покладіть підготовлені кістки у воду, повільно нагрівайте, знімайте піну й додайте ароматичні овочі. Для темної попередньо запечіть кістки та частину овочів без підгоряння, деглазуйте деко й томіть. Обидві основи процідіть і швидко охолодіть.`},{title:`Практичний дослід`,text:`З однакової кількості курячих кісток зробіть світлу й темну основу, запікши лише другу партію. Порівняйте аромат, колір, густоту та доречність для легкого супу й темного соусу.`},{title:`Поширені помилки`,text:`Підгорілі кістки дають гіркоту, а не глибину смаку. Бурхливе кипіння робить основу каламутною, надмірне раннє соління заважає подальшому уварюванню. Темніший колір не доводить більшого вмісту желатину.`},{title:`Пов’язані теорії`,text:`161, 164, 165, 172.`}]};var l=[161,164,165,172];var c=`References / Джерела`;var d=[`https://app.ckbk.com/section/prof90208c08s001ss002sss002/preparing-white-stocks`,`https://app.ckbk.com/section/prof36725c08s001ss001sss002ssss003/preparing-brown-stocks`];var h={id:162,slug:s,group:`161`,title:r,en:n,ua:a,related:l,referenceTitle:c,references:d};export{h as default,n as en,i as group,o as id,c as referenceTitle,d as references,l as related,s as slug,r as title,a as ua};